-- F79 completion (2026-11-02): a status CHECK on every status column and every JSONB status the app writes, each
-- list read from the code's writers (Rule 11). NOT VALID: new writes are checked, existing rows are not scanned or changed
-- (Rule 8; tools/launch/list-status-violations.js lists any that do not fit). Idempotent; mirrors database.js initDB().
DO $$ BEGIN IF to_regclass('accountant_clients') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_accountant_clients_status') THEN ALTER TABLE accountant_clients ADD CONSTRAINT chk_accountant_clients_status CHECK (COALESCE(status, '') = '' OR lower(status) IN ('pending','active','suspended','revoked','expired','rejected')) NOT VALID; END IF; END $$;
